INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frebbventure', 'If you ever wondered how a Kirby inspired action-platformer would play if you ditched the copy gimmicks and smashed the speedometer, Frebbventure is the game for you! With four playable characters, you''ve got plenty of movesets to master, and a variety of special bonus medals will reward you for learning the levels, too. Collect them all to unlock bonus stages, and peel back the layers of a shocking secret.
