INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ViragoHerstory Go!', 'Join Willow, the brave hero of the Virago series, in ViragoHerstory Go! a thrilling hexagon block puzzle adventure. Walk on blocks, avoid traps, and escape enemies in a fast-paced challenge where every move matters. Blocks crumble if you stay too long, cannons fire at you, and traps are everywhere. Can you survive and outsmart every obstacle?' FROM games WHERE igdb_id = 374742 ON CONFLICT (game_id, language_code) DO NOTHING;
