INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skull Island: Rise of Kong', 'Embark on a 3rd person action-adventure quest to avenge the death of your parents at the hands of the ultimate alpha predator: Gaw. Conquer waves of primal beasts and defeat the minions of your arch-nemesis on your way to becoming the rightful King of Skull Island. Traverse the mysterious island and uncover lore and all the secrets the island has to offer as you encounter swamps, waterfalls, jungle, and skullite-filled caves that give the island’s flora and fauna its power.' FROM games WHERE igdb_id = 257674 ON CONFLICT (game_id, language_code) DO NOTHING;
