INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Heat Unleashed', 'The sequel to the 2010 arcade hit, “Dead Heat Unleashed” is an intense new racing game with four new courses, new cars, and an attractive LED lit cabinet that responds to the game, changing lighting patterns during gameplay. Link up to four cabinets to challenge players head-to-head in tight races that are sure to be a dead heat every time! Players charge their ULTIMATE HEAT gauge through aggressive racing and crowding their rivals.
