INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zx-spectrum-pac-man-arcade', 281479, '2023-12-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9dsx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq10l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZX Spectrum Pac-Man Arcade', 'This is a faithful conversion of the original Pac-Man arcade for the ZX Spectrum 48K. Everything was recreated with as much detail as possible through hours of reading of multiple Pac-Man guides and playing the original game. Being a conversion, some concessions were made to work around the limitations of the 48K but the overall result is still pretty close. The game runs at a silky smooth 50fps with game sound and no tearing or flickering.
