INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Underlevel', 'Underlevel is a game where you play as a horde of skeletons while a player is raiding the dungeon, trying to get as much XP as they can so they level up and potentially kill the boss at the end - it''s your job to stop that from happening. Try your best to rescue all the skeletons, destroy all the loot and keep the player from levelling up before they make it to the final floor.' FROM games WHERE igdb_id = 256119 ON CONFLICT (game_id, language_code) DO NOTHING;
