INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby: Wacky Episode', 'A bite-sized fan made adventure is coming your way! Explore those worlds, pull off some new insanely stylish moves and dash through levels at an exhilarating pace! Equip yourself with 2 copy abilities at once and duel with some of Kirby''s past foes yet again! Alongside Story Mode, 3 unlockable game modes are now available for players to push their skills to the maximum. This sure is going to be a wacky time you won''t wanna miss!' FROM games WHERE igdb_id = 315520 ON CONFLICT (game_id, language_code) DO NOTHING;
