INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mystery-case-files-a-crime-in-reflection-collectors-edition', 283552, '2023-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coawa1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4qi7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Case Files: A Crime in Reflection - Collector''s Edition', 'Just when you thought it was safe to take a vacation, the Crown calls you back into action! While burglary cases aren’t the Master Detective’s typical area of investigation, the police are stumped when a royal coronation scepter is stolen from one of the most secure museums in the world in the latest of a series of similar incidents, and they’re turning to you for help. The thieves have proven to be careless but crafty, somehow able to get in and out of the most secure locations in seconds and disappear into thin air! But what starts as a simple series of heists quickly spirals out of control when the criminals awaken something that will put them, the Master Detective, and even the world itself in grave danger! Can you unlock the bloody secrets the thieves discovered and save the day? There’s only one way to find out, Detective! Crack the case in this all-new Hidden-Object Puzzle Adventure!' FROM games WHERE igdb_id = 283552 ON CONFLICT (game_id, language_code) DO NOTHING;
