INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Failure Drill', 'A 2D, singleplayer adventure game set in the near future. The player controls Claire on her journey as a soldier in a mysterious war, while also attempting to solve the enigmas her identity and reality hinged upon before. This game is a drama with psychological horror themes and stylized 2D art.' FROM games WHERE igdb_id = 241518 ON CONFLICT (game_id, language_code) DO NOTHING;
