INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WBSC eBaseball: Power Pros', 'Experience the virtual world of baseball available in WBSC eBASEBALL: POWER PROS. The most played baseball game series in Japan is now featured in the World Baseball Softball Confederation’s eSport discipline. Whether you like swinging for the fences or pitching in the strike zone, you know baseball is all about batting, pitching, and fielding. The virtual world of baseball is no different. With easy pick-up-and-play mechanics, WBSC eBASEBALL: POWER PROS is fun for both novices and skilled gamers' FROM games WHERE igdb_id = 236674 ON CONFLICT (game_id, language_code) DO NOTHING;
