INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block ‘Em Sock ‘Em', 'Your goal in Block''Em Sock''Em is to control John Hancock through 25 different levels to destroy boxes of the same color. Your aim is to get the block counter below the goal number with a limited number of tosses. If you toss a colored block and it hits another color, then your block will change to that color. There are three difficulty settings.' FROM games WHERE igdb_id = 381135 ON CONFLICT (game_id, language_code) DO NOTHING;
