INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mixture', 'Mixture is a VR fantasy action-adventure in which two enemies in an alliance of necessity traverse barren worlds in a quest for redemption. In this dual character control game, you alternate between playing as the master alchemist Sephairos and exiled knight Sola, in both first and third person perspectives. As an odd couple, you must platform, mix materials, cast and melee, solve puzzles, and defeat giant bosses to survive this atmospheric tale.' FROM games WHERE igdb_id = 237776 ON CONFLICT (game_id, language_code) DO NOTHING;
