INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Across The Void', 'Across The Void is an exciting new roguelike video game that will take you on a journey through a universe of endless possibilities. Featuring randomly generated maps and side maps, the game offers a new adventure every time you play. With a unique skill system, players can create their own playstyle by investing in three different trees, each with its own set of skills tailored to different playstyles. With over 50 skills to unlock, you can customize your character to your liking and take on the universe on your own terms.' FROM games WHERE igdb_id = 248133 ON CONFLICT (game_id, language_code) DO NOTHING;
