INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Y+1: Operation X.M.A.S.', 'Mega Man Y+1: Operation X.M.A.S. is a bite-sized Mega Man adventure to save Christmas! Featuring 9 unique stages, you''ll be taken to all sorts of locales in the hunt for your misplaced belongings. With fortresses made of gingerbread, summery beaches south of the equator, and even Dr. Wily''s own chimney, there''s no telling where you''ll need to go. Don''t dawdle, though - these levels don''t pull any punches, and you''ve got time trial records to beat! Aim for gold!' FROM games WHERE igdb_id = 279729 ON CONFLICT (game_id, language_code) DO NOTHING;
