INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avatar: Frontiers of Pandora', 'Avatar: Frontiers of Pandora is a first-person, action-adventure game set in the never-before-seen Western Frontier of Pandora. Abducted by the human militaristic corporation known as the RDA, you, a Na’vi, were trained and molded to serve their purpose. Fifteen years later, you are free, but find yourself a stranger in your birthplace. Reconnect with your lost heritage, discover what it truly means to be Na''vi, and join other clans to protect Pandora from the RDA.' FROM games WHERE igdb_id = 152202 ON CONFLICT (game_id, language_code) DO NOTHING;
