INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet Her There', 'An intense, intimate narrative game in 2 colors. Explore a tiny, giant world of two people, stuck in a cursed time loop. Relive a single day as many times as needed. Ask for help. Don''t get arrested. Find the correct steps to try and save the person you love. Is it not too late?' FROM games WHERE igdb_id = 263786 ON CONFLICT (game_id, language_code) DO NOTHING;
