INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chicken Fight', 'Chickens, baseball bats and rockets, need more? Fight other player chickens in a fast-paced platformer fighter where you use the environment to defeat your enemies. Pick up fishing rods, jetpacks, net guns, and even other chickens. Also defeat an evil duck in story mode or create maps in the editor.' FROM games WHERE igdb_id = 238625 ON CONFLICT (game_id, language_code) DO NOTHING;
