INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruled by Rule', 'Dive into the depraved world of Ruled by Rule, an engaging RPG where the stakes are high and the consequences are… stimulating. This isn''t your typical hero''s journey; here, villains hold the power, and the Public Order Princesses are at their mercy. Prepare for intense combat, strategic decision-making, and a unique erotic specialization that sets this game apart.' FROM games WHERE igdb_id = 369279 ON CONFLICT (game_id, language_code) DO NOTHING;
