INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DesperaDrops', 'A crime-romance set in Summer 2028, Italy where exchange student Mika Amamine finds herself embroiled in murder case and she is a suspect. While being escorted to be further interrogated, she is freed when her vehicle gets overturned in an incident–on top of all this there is a mysterious assailant who is after Mika’s “powers” and she finds herself trying to escape both the police and the assailant with 6 other people who all have a criminal past.' FROM games WHERE igdb_id = 273614 ON CONFLICT (game_id, language_code) DO NOTHING;
