INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Picket Line', 'Picket Line is a casual single-player tower defense game that tells the story of a factory strike in 20th century Europe. Players act as the Union by controlling the workers who form a picket line. The goal of the game is to block any potential workers who want to enter the factory to keep it working (popularly known as Scabs), and to hold the strike long enough until the factory gives up and accepts the Union''s terms.' FROM games WHERE igdb_id = 249714 ON CONFLICT (game_id, language_code) DO NOTHING;
