INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soundodger 2', 'Soundodger 2 is an experimental dodge-em-up music game that turns every song into a choreographed dance of bullets, lasers, and challenges to weave through in order to survive. The sequel to 2013''s award-winning Soundodger+, Soundodger 2 is bigger, better, and dodgier than ever before. With an all-new selection of songs from international musicians and a fully-featured level editor to use your own music, you''ll never run out of things to dodge.' FROM games WHERE igdb_id = 140864 ON CONFLICT (game_id, language_code) DO NOTHING;
