INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oni No Kenkyuushitsu', 'Oni No Kenkyuushitsu ("Laboratory Of The Oni") is a sequel to Oni No Yakata, set 10 years in the future, in the year 2028. You once more play as Ayana Hasegawa as she enters a new job as an intern at Crovich Research Facility, hoping to find a solution to the existence of the Oni that cost her the life of one of her friends, and the lives of many others before them. Little does she know, a combination of poor containment procedures and upper management with ulterior motives will cause the facility to unexpectedly release its specimens and cause chaos.' FROM games WHERE igdb_id = 286761 ON CONFLICT (game_id, language_code) DO NOTHING;
