INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beat Banger', 'Beat Banger is a mature furry rhythm game. You are the lone protagonist in a rags-to-bitches story. Work your way to the top of Beat Banger Studios, a small and rhythmic porn production company in desperate need of assistance. You apply for a simple production job, but the CEO has another position in mind for you. Jump in now. You won''t want to miss a beat.' FROM games WHERE igdb_id = 253039 ON CONFLICT (game_id, language_code) DO NOTHING;
