INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farting Simulator', 'Get ready for a gut-busting good time with Farting Simulator! You experience the joy of controlling an uncontrollable bodily function in a meme-filled and comedic open-world sandbox environment. Farting Simulator is a hilarious and entertaining adventure that''s sure to leave you FARTING out loud.' FROM games WHERE igdb_id = 315285 ON CONFLICT (game_id, language_code) DO NOTHING;
