INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Souls of Tartarus', 'Souls of Tartarus is a "Rogue-lite", "Souls-like" inspiered Top-Down Dungeon Crawler. A gamble with the ruler of the Underworld "Tartarus" gives you a last chance to be reborn. Can you defeat his Generals that became lazy and set in there ways? No Checkpoints. No Saves. One Run, One Chance.' FROM games WHERE igdb_id = 226619 ON CONFLICT (game_id, language_code) DO NOTHING;
