INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kamiji', 264056, '2023-07-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70dv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sco85r.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamiji', 'Kamiji is a Japanese-learning AR trading card game that finds magic in the mundane! Following a volcanic eruption the creatures known as Kami were propelled out of the earth. They were lost and had no homes... But fortunately the ancient humans of China and Japan had hoped and anticipated that they would come home. And forged their entire writing system of the image of the Kami, knowing that one day they would have domains to return to. So the Kami finding these shrine-like remembrances of themselves buried themselves within the kanji. They might''ve gone completely unnoticed had it not been for a team of scientists who developed a new technology in the form of an app, called Kamiji. Players can use it to scan kanji characters on outdoor billboards that were covered in volcanic ash of the eruption to capture and tame the Kami living within each kanji character.' FROM games WHERE igdb_id = 264056 ON CONFLICT (game_id, language_code) DO NOTHING;
