INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fazbear Fright Attraction', 'Fazbear''s Fright Attraction, otherwise known as FNaF 3: PLUS by fans is an indie point-and-click fangame developed by LostPawPlay, taking inspiration from Phisnom''s cancelled project Five Nights at Freddy''s Plus to create a sequel based around his original recreation of Phisom''s works, FNaF Plus Restored. Like his initial release, Fazbear''s Fright Attraction is an alternative take on Scott Cawthon''s Five Nights at Freddy''s 3.' FROM games WHERE igdb_id = 271054 ON CONFLICT (game_id, language_code) DO NOTHING;
