INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War Operation: Full Contact', 'WAR OPERATION: Full Contact is a third-person shooter game, its first early access version features multiplayer network mode and sends you straight back to April 2003, in the heart of Iraq, in the midst of a frighteningly intense confrontation. The Iraqi army against the U.S. Marines, choose your side, your class, your weapons and run through the streets of Baghdad, near Firdos Square, frozen in the days of Saddam Hussein''s regime. A unique and exceptional experience never seen before.' FROM games WHERE igdb_id = 220530 ON CONFLICT (game_id, language_code) DO NOTHING;
