INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defi Kingdoms', 'DeFi Kingdoms is a cross-chain, play-to-earn game built on a strong DeFi protocol with plans to become a fully-fledged MMORPG in later phases of the Roadmap. The game features DEXs, liquidity pool opportunities, and a market of rare, utility-driven NFTs, which all together create a beautiful, immersive online world in the incredibly nostalgic form of fantasy pixel art. DeFi Kingdoms currently lives on the Harmony and DFK Chain blockchains' FROM games WHERE igdb_id = 185371 ON CONFLICT (game_id, language_code) DO NOTHING;
