INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sun''s Edge', 'What would you do if the world was ending? In Sun''s Edge, you are a ranger exploring the island of Solasta, trying to find a way to keep the world from falling to darkness! In this Aztec themed adventure game, you will need to fight, climb, and solve your way out of problems. Everyone is counting on you!' FROM games WHERE igdb_id = 306880 ON CONFLICT (game_id, language_code) DO NOTHING;
