INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sins of Treatment', 'Sins of Treatment is a 3D horror from the first person, everything happens in some liminal spaces. The gameplay consists in collecting information, solving riddles and escaping from various entities. The main goal is to understand what is happening to you, how you got here and who you were before.' FROM games WHERE igdb_id = 275362 ON CONFLICT (game_id, language_code) DO NOTHING;
