INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dāi Dāi Dà Màoxiǎn', '“Dāi Dāi Dà Màoxiǎn” is a 2D turn-based RPG where players take on the role of Dāi Dāi, a boy born in the Xia dynasty. Along the journey, you will befriend companions, collect the Five Spirit Orbs, and gradually uncover the dark truth behind an evil cult. The game also features a Roguelike mode and challenging dungeon gameplay, offering players a rich and diverse experience.' FROM games WHERE igdb_id = 368138 ON CONFLICT (game_id, language_code) DO NOTHING;
