INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lies as a Starting Point', 'Lies as a Starting Point is a branching visual novel that follows Kanata and Nozomi, two strangers who meet on a train. Through Nozomi’s stories about three pairs of men and women and their “lies,” Kanata begins to question reality and uncover hidden truths. The narrative splits into three distinct routes—junior high, high school, and university—each revealing new facets of Nozomi’s past. Reaching the true end of each chapter unlocks deeper layers of the mystery.' FROM games WHERE igdb_id = 258507 ON CONFLICT (game_id, language_code) DO NOTHING;
