INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('where-the-anemones-bloom', 302118, '2023-05-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co88k1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3hnk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where the Anemones Bloom', 'Cordelia leads a life that most mermaids would envy. She has close friends and is part of a prominent pod, her future is all planned out. But Cordelia isn’t most mermaids. When her pod moves to the coast, she’s warned about the forbidden shallows and the dangers that lurk beyond. She’s heard all the rumours of course, but none of her friends will go near it. Curiosity gets the better of Cordelia, and she soon finds herself trembling at the fearful lights and hum of this strange city. However, something - someone actually - has also caught her eye. What starts as mere curiosity blossoms into something far more interesting. Soon Cordelia questions who she really is, and what she really wants. As she ventures further into uncharted territory, she gets closer to love but further from who she is and what she knows. Will she risk it all for a taste of the forbidden?' FROM games WHERE igdb_id = 302118 ON CONFLICT (game_id, language_code) DO NOTHING;
