INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clockwork Survivors', 'Don''t hold forward, don''t press fire, but focus on the vertical in this autorunning reverse bullet hell roguelike. Master the level layout by lapping the same short section several times while you gather steam for your hot air balloon companion. Make the balloon & yourself happy.' FROM games WHERE igdb_id = 223512 ON CONFLICT (game_id, language_code) DO NOTHING;
